#' {testthat}. This line can be more than 80 characters.

# ad_fabs ----
## Setup ----
# The default smoothing constant.
smoothing_constant <- 1e-5
values <- c(-10, -1, -0.1, 0.1, 1, 10)

## IO correctness ----
test_that("`ad_fabs()` works with correct inputs", {
  #' @description Test that `ad_fabs(-3)` returns sqrt(9 + 1e-5), the smooth absolute value with the default constant.
  expect_equal(
    object = FIMS:::ad_fabs(-3),
    expected = sqrt(9 + smoothing_constant)
  )
  #' @description Test that `ad_fabs()` with a smoothing constant of 0 equals `abs()`.
  expect_equal(
    object = FIMS:::ad_fabs(values, C = 0),
    expected = abs(values)
  )
  #' @description Test that `ad_fabs()` gives x and -x the same value.
  expect_equal(
    object = FIMS:::ad_fabs(values),
    expected = FIMS:::ad_fabs(-values)
  )
})

## Edge handling ----
test_that("`ad_fabs()` returns correct outputs for edge cases", {
  # sqrt(x^2 + C) - |x| = C / (sqrt(x^2 + C) + |x|), which is above 0 and
  # below C / (2 |x|).
  smoothing_error <- FIMS:::ad_fabs(values) - abs(values)
  #' @description Test that `ad_fabs()` is always above `abs()`.
  expect_true(all(smoothing_error > 0))
  #' @description Test that `ad_fabs()` is above `abs()` by less than C / (2 |x|), e.g., 5e-7 at |x| = 10.
  expect_true(all(smoothing_error < smoothing_constant / (2 * abs(values))))
  #' @description Test that `ad_fabs(0)` returns sqrt(C), about 0.0032, the largest difference from `abs()`.
  expect_equal(
    object = FIMS:::ad_fabs(0),
    expected = sqrt(smoothing_constant)
  )
})

## Error handling ----
# No built-in errors to test.

# ad_max ----
## Setup ----
# No setup required.

## IO correctness ----
test_that("`ad_max()` works with correct inputs", {
  #' @description Test that `ad_max(2, 5)` returns (7 + sqrt(9 + C)) / 2, the smooth maximum with the default constant.
  expect_equal(
    object = FIMS:::ad_max(2, 5),
    expected = (7 + sqrt(9 + smoothing_constant)) / 2
  )
  #' @description Test that `ad_max()` with a smoothing constant of 0 equals `pmax()`.
  expect_equal(
    object = FIMS:::ad_max(values, 0.5, C = 0),
    expected = pmax(values, 0.5)
  )
  #' @description Test that `ad_max()` gives the same value when its 2 arguments are swapped.
  expect_equal(
    object = FIMS:::ad_max(values, 0.5),
    expected = FIMS:::ad_max(0.5, values)
  )
})

## Edge handling ----
test_that("`ad_max()` returns correct outputs for edge cases", {
  # ad_max(a, b) - max(a, b) = (ad_fabs(a - b) - |a - b|) / 2, so it is above
  # 0 and below C / (4 |a - b|).
  smoothing_error <- FIMS:::ad_max(values, 0.5) - pmax(values, 0.5)
  #' @description Test that `ad_max()` is always above the larger of its 2 arguments.
  expect_true(all(smoothing_error > 0))
  #' @description Test that `ad_max()` is above the larger of its 2 arguments by less than C / (4 |a - b|).
  expect_true(all(
    smoothing_error < smoothing_constant / (4 * abs(values - 0.5))
  ))
  #' @description Test that `ad_max(1, 1)` returns 1 + sqrt(C) / 2, the largest difference from `max()`, when the 2 arguments are equal.
  expect_equal(
    object = FIMS:::ad_max(1, 1),
    expected = 1 + sqrt(smoothing_constant) / 2
  )
  # The model guards denominators with ad_max(x, 1e-8). For x well above
  # 1e-8, the guard leaves x within C / (4 x).
  #' @description Test that `ad_max(0.862, 1e-8)` changes 0.862 by less than C / (4 times 0.862), about 3e-6.
  expect_lt(
    object = FIMS:::ad_max(0.862, 1e-8) - 0.862,
    expected = smoothing_constant / (4 * 0.862)
  )
})

## Error handling ----
